/* Evolvlings: English text for the era 6 path conversations (parallel to events-era6.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Delivery 1: the shadow wells, the queen, the Named One, the culprit who forgot and the end ==================== */

  add("hollow", {
    "e6-pozos": { who: { desmemoria: "Desmemoria, of the well" }, nodes: {
      a: { say: ["At the bottom of the Hollow there is a long queue that runs down the slope and disappears into the dark. At its end, in a cave, there are three round wells. They hold no water: they hold shadow, still, thick, breathing.",
                 "I'm Desmemoria. I tend the middle well. You lean over, breathe deep, and think of what you want to stop remembering. When you come up, it's gone. One coin per memory.",
                 "A hundred and twelve came today. A widow, a thief, a boy who hit his brother. They all come for the same thing: the winter. What they did, what they didn't do."],
           opts: ["“Where does what's forgotten go?”", "“Does the Court keep anything?”", "Help Desmemoria tend the queue", "Look into a well, without breathing", "Leave"] },
      adonde: { say: ["Down. I don't know where. The shadow takes it and doesn't give it back. I've never seen anyone get anything back.",
                      "My grandmother said the shadow belongs to the Root. That the Root swallows what we forget. I don't know if it's true. It's what the Court says when it wants to scare children."] },
      corte: { say: ["The coin. And a list: who came. Not what they forgot: nobody knows that, not even me. Just the name.",
                     "I forget the list every night. The queen asked me to. That way nobody can make me tell it."] },
      atender: { say: ["You spend the afternoon in the cave. You give an old woman your hand so she doesn't fall into the well. You pass a handkerchief to a man who cries before leaning over.",
                       "A boy arrives with a coin and doesn't know what he wants to forget. Desmemoria gives him back the coin and sends him home.",
                       "If he doesn't know what to forget, there's nothing to forget. That's my rule. The Court doesn't have it. Thanks for the afternoon. I can't remember the last time someone helped me, and it isn't the well's doing."] },
      mirar: { say: ["You lean over the middle well without breathing. The shadow stirs. Inside, very far away, things go by: a face, a door, a hand giving bread. Other people's memories.",
                     "One stops and looks at you. It's a lullaby. Someone forgot it here. You recognise it: it's the Star's.",
                     "Come out. Come out. If you breathe in there, you don't know what you'll lose. Some people came to forget a debt and forgot their daughter."] },
      irte: { say: ["You climb the slope, against the queue. Nobody looks at you. They all look at the ground, rehearsing under their breath what they're going to forget."] },
    } },

    "e6-olvidar": { who: { desmemoria: "Desmemoria, of the well" }, nodes: {
      a: { say: ["It's late. The queue is over. Desmemoria sits on the rim of the middle well, his feet dangling over the shadow.",
                 "You carry a book. I've seen it. It remembers things from before, from long before. Things people paid to forget.",
                 "I won't charge you. If you like, you can leave something here. Something from before that weighs on you. What happens in the well stays in the well. Your book will have one page gone grey."],
           opts: ["“What did you forget?”", "Lean over and forget something from a past era", "“No. What happened, happened. I'll carry it.”"] },
      usted: { say: ["My mother. She died in the Deep's queue, the last winter. I remember she existed. I don't remember her face. I traded it to be able to sleep.",
                     "That's why I work here. So nobody suffers what I suffered. And sometimes I think what I suffered was the only thing I had left of her."] },
      olvidar: { say: ["You lean over. You breathe deep. The shadow is cold and smells of wet earth. You think of something from before, something that hurt.",
                       "When you come up, you don't know what it was. You know there was something. In the Book, one page has blurred letters, as if someone had poured water on them.",
                       "There. Feel lighter? Most say yes. Some come back a month later to ask me what they forgot. I don't know. Nobody knows."] },
      negarte: { say: ["You'll carry it. Well. How strange. Most people pay not to carry.",
                       "He looks at the shadow a long while.",
                       "I'd carry it too, if I could go back. But I don't know what I'd carry anymore. That's the trouble with the well: it won't let you regret properly."] },
    } },

    "e6-noctambula": { who: { noctambula: "Queen Noctámbula" }, nodes: {
      a: { say: ["In the Veiled Court's deepest hall, behind seven curtains of smoke, a young woman in a long veil counts coins on a stone table. She has the dark rings of someone who doesn't sleep.",
                 "I'm Noctámbula. Queen of the Court, granddaughter of Calígine, and by blood, of Lóbrego. The Court already lost its land once. It won't lose it again.",
                 "I sell forgetting. I didn't invent it: the shadow was there. I only set up a queue and a price. If I don't sell it, anyone will, dearer and without care."],
           opts: ["“The Chronicle blamed the Court. Do you sell forgetting so that's forgotten?”", "“The Chronicle blamed the Houses. And the Court?”", "“What does the Court keep that nobody knows?”", "“I promise not to tell what you tell me.”", "“Tell everyone what you know.”", "Leave without promising anything"] },
      culpa: { say: ["You say it as if it were bad. The Chronicle blamed us for a Root everyone woke. Three generations carrying that. Why wouldn't we want it forgotten?",
                     "What bothers me isn't that they forget it. It's that they forget it and keep looking at us the same way. Hatred stays even when the reason goes."] },
      casas: { say: ["The Houses carried the blame, yes. And they're the ones who pay most to forget it. They come at night, hooded. I charge them double.",
                     "It isn't revenge. Their guilt weighs more, so the well works harder. That's what I say."] },
      secreto: { say: ["A secret. Every queen knows it, and none has told it. It's no use anymore, but it's kept. That's how Court secrets are: they're kept because they were kept.",
                       "If you promise not to tell it, I'll tell you. If not, I'll take it with me like my grandmother."] },
      prometer: { say: ["Noctámbula lifts her veil a little. Her eyes are red.",
                        "What's forgotten in the well doesn't vanish. It goes down to the Root. The Root keeps everything. Every memory we sell, the Root carries, and it forgets a little of itself.",
                        "My grandmother knew. My great-grandfather too. And we sell anyway, because the Court has to eat. There. Now you carry it too."] },
      pedir: { say: ["Everyone? You don't understand the Court. If I tell a secret, I stop being queen. The queen is the one who keeps.",
                     "She looks at you a long while. Then she goes back to counting coins.",
                     "Come back when you know what you're asking. I do know. That's why I don't say it."] },
      irte: { say: ["You leave through the seven curtains. Behind you, the sound of coins doesn't stop."] },
    } },

    "e6-nombrada": { who: { gualda: "Gualda, the Named One" }, nodes: {
      a: { say: ["At the entrance to the Hollow, sitting on a stone, a shadow woman in worn clothes greets everyone who passes. She says the same thing to all of them, as if she couldn't help it.",
                 "Gualda of the Third Curtain, daughter of Umbrío. That's my true name. There, I said it. I say it to everyone. I can't keep it in.",
                 "In the Court, a true name isn't spoken. Whoever knows it knows how to make you forget. My brother shouted it in a fight, in front of everyone. Since then I've been cast out. A shadow with her name spoken is an open door."],
           opts: ["“Why can't you keep it in?”", "Take her back to the Court and speak for her", "“Choose a new name. One nobody knows.”", "“There's life outside the Court too.”"] },
      porque: { say: ["When a true name is spoken aloud, it gets loose. It isn't only yours anymore. It slips out of your mouth on its own, like hiccups.",
                      "The other shadows say it's the Root's punishment. I think it's something else: that a name wants to be said. We kept it quiet for a thousand years."] },
      volver: { say: ["You go with Gualda to the Court's door. The guards cover their ears when she says her name. You talk with the chamberlain a whole hour.",
                      "In the end they let her in, through the back door, to the kitchen. Not the hall. The kitchen.",
                      "Gualda of the Third Curtain, daughter of Umbrío, kitchen help. It's longer, but it's mine. Thank you. The Court remembers who brings its own back. For better and for worse."] },
      nuevo: { say: ["A new name? Made up?",
                     "She thinks a long time. Then she comes close and says something in your ear. A short word. She doesn't repeat it.",
                     "That one. Only you know it. If I ever say it aloud, I'll know you betrayed me. Meanwhile, I keep saying the other. The other can't do anything to me anymore."] },
      fuera: { say: ["Outside. Yes. Gualda of the Third Curtain, daughter of Umbrío, who lives outside. Sounds like nothing.",
                     "She gets up, brushes off her clothes and heads for the Meadow. To every person she passes she says her name. Some answer with theirs.",
                     "A while later, in the distance, you hear her laughing with someone. A shadow's laugh, odd, short."] },
    } },

    "e6-legajo": { who: { legajo: "Legajo, archivist of the Veil" }, nodes: {
      a: { say: ["In a dry gallery of the Court, among shelves of scrolls and boxes of paper, a thin man with smoked-glass spectacles copies an old scroll by hand. He has ink up to his elbows.",
                 "Legajo, archivist of the Veil. I copy everything people come to forget. What can be known, at least: who came, from where, what face they wore. The archives have to survive the forgetting. Otherwise, who remembers?",
                 "Beside the table, on the floor, there's a torn-out page, crumpled into a ball. Legajo covers it with his foot when he sees you looking."],
           opts: ["“What does that page say?”", "Ask him to let you read the page", "“Copy the archives for the Hondura. Let there be two.”", "Let him burn it"] },
      pagina: { say: ["Nothing. Something of mine. From the winter. We all have a page like that.",
                      "I tore it out myself. I could go to the well, but no: an archivist doesn't forget. He tears out. It's different. What's torn out still exists somewhere."] },
      leer: { say: ["Legajo hesitates. Then he lifts his foot and lets you have the page. You smooth it on the table.",
                    "It's a list from the last winter. Names of shadows who asked the Court for blankets and didn't get them. At the bottom, in Legajo's hand: “I didn't give them. I was ordered. I could have given them anyway.”",
                    "There. You've read it. Now it exists in two heads. I'll glue it back into the scroll. It costs me, but an archive with torn-out pages isn't an archive."] },
      copiar: { say: ["For the Hondura? For the wall carvers? We've never shown them anything.",
                      "But he agrees. For a week you carry scrolls down to the Caves, at night, in a sack. The Hondura copies them into the stone, word for word.",
                      "Two archives. One of paper, which burns. One of stone, which doesn't. If the queen finds out, she'll throw me out. But the names will survive."] },
      quemar: { say: ["Legajo holds the page to the candle. It burns fast. The ashes fall onto the scroll he was copying and he blows them away.",
                      "Done. That didn't happen. I didn't forget it: I burned it. An archivist has the right to one page. Just one."] },
    } },

    "e6-comercio": { who: { noctambula: "Queen Noctámbula", desmemoria: "Desmemoria, of the well" }, nodes: {
      a: { say: ["The queen receives you in the cave of the wells, at night, with no queue. Desmemoria stands beside her, hands behind his back.",
                 "You've walked the whole Glade. You've seen what the well does. I offer you something: the Court's forgetting, for whatever you want.",
                 "The Meadow and the Quarter have hated each other since the winter. The Tides and the Deep too. If I bring them all to the wells together, they forget the hatred. One afternoon. Free. In exchange, the Court keeps its land forever, by law."],
           opts: ["“What happens to what they forget, down below?”", "“I'm going to expose it. Everyone will know what the well does.”", "“Do it. Let them forget the hatred.”", "“I'll buy your policy: the Court stops selling.”"] },
      abajo: { say: ["It goes down. I've told you already, or someone will. The Root keeps it. With every hatred forgotten, the Root forgets the pact a little more.",
                     "My lady. You never said it aloud.",
                     "I'm saying it now. Forgetting isn't free. But neither is hatred."] },
      denunciar: { say: ["The next day you tell it in the Meadow, in the Crater, in the Forest. That what's forgotten goes down to the Root. That the Court knew.",
                         "The queues shrink. A week later, hardly anyone comes. The Court runs out of coins. People go home carrying what they meant to forget.",
                         "Good. Now the Glade remembers everything, and the Court is hungry. You chose for my people and for yours. My people won't forget it. And no well can cure that."] },
      usar: { say: ["One afternoon the queue is two peoples. Meadow folk and Quarter folk, shoulder to shoulder, not looking at each other. One by one they lean over the well.",
                    "When they come up, they look at each other. They don't know why they were so grim. Someone laughs. That night they eat in the same square.",
                    "It worked. It worked. I've never seen anyone come up smiling.",
                    "And nobody will remember why they hated each other. Nor what they learned by hating. That's the deal."] },
      comprar: { say: ["Buy? With what?",
                       "You offer what you have: your coins, your word in the Heart, that the Court has a voice whenever land is discussed.",
                       "Your word. Good. The Court stops selling. The wells are capped with stone. In exchange, when the peoples gather, the Court sits in the front row. And its land isn't up for discussion.",
                       "And the people who come tomorrow, my lady? What will they sleep with?",
                       "With what they have. Like before. Like us."] },
    } },

    "e6-verso": { who: { legajo: "Legajo, archivist of the Veil", gualda: "Gualda, the Named One" }, nodes: {
      a: { say: ["Legajo sends a Court boy to fetch you. You find him in the archive gallery with Gualda, who sits on a box, very still.",
                 "I found something in the oldest scrolls, from before the first exile. A verse. The ninth. The one that isn't in the lullaby. It says how the pact ends.",
                 "If I copy it, someone will sell it at the well. If I burn it, it's lost. It has to be kept somewhere it can't be forgotten or sold.",
                 "Gualda of the Third Curtain, daughter of Umbrío. Sorry. Listen: a true name isn't forgotten in the well. It's the only thing that doesn't go. If the verse is hidden inside a name, nobody can take it out."],
           opts: ["“What does the verse say?”", "Hide the verse inside a true name", "Tell it to everyone, so nobody can sell it"] },
      dice: { say: ["I don't understand it well. It speaks of the Root and of whoever tends it. Of what is owed to it. It says the pact isn't paid with a song: it's paid with something remembered.",
                    "The rest I can't read. The ink is old. Or I am. Both."] },
      nombre: { say: ["Mine has already been said. It's no use. We need one nobody has heard.",
                      "Legajo brings his granddaughter, a shadow girl of six. She has no true name yet: in the Court it's given at seven. Legajo writes the verse on a paper, reads it into her ear and burns the paper.",
                      "Her name will be the verse. When she says it, she'll say it. While she keeps quiet, she keeps it. She'll have to live in hiding. All her life. And her children after.",
                      "Poor thing. Poor thing. I know what a name weighs."] },
      todos: { say: ["That week the verse is read aloud in the Meadow square, at the Forge, at the Court's door. Legajo reads it with a trembling voice. People copy it onto walls, tally boards, blankets.",
                     "A month later the verse is sung in the taverns to another tune. Some change the words. Nobody knows anymore which is the true one.",
                     "They can't sell it. Everyone has it. But everyone has it differently. I don't know if I saved it or broke it."] },
    } },
  });

  add("aurora", {
    "e6-vecinos": { who: { rastrojo: "Rastrojo, of the Quarter" }, nodes: {
      a: { say: ["On a Quarter street, two houses have doors painted different colours and a fence of sticks between them. At each window someone glares at the other.",
                 "Rastrojo, of the Quarter. That's my house, the blue one. Across are the green ones. We haven't spoken since the winter. I don't remember why. I went to the well. So did they.",
                 "The strange thing is the anger didn't go. I get up and I hate them. I don't know what for. It's like being hungry with no stomach."],
           opts: ["“Doesn't anyone remember what happened?”", "Search the Caves for what happened between the two houses", "Sit them down to eat at the same table, without explaining anything", "“If they don't remember, there's nothing to fix.”"] },
      nadie: { say: ["The kids don't. They were kids. My grandmother remembers, but won't say. She says if I paid to forget, she won't give it back for free.",
                     "So I live hating something my grandmother knows and I don't. Strange, isn't it?"] },
      buscar: { say: ["In the Caves, the Hondura carves everything. You find the two houses on a wall, in small letters: “Winter. The green one hid firewood. The blue one stole it. A child of the green died. An old woman of the blue died.”",
                      "You read it to Rastrojo. He goes quiet a long while.",
                      "Ah. That was it. Now I know why I hate them. And I know why they hate me. I don't know if it's better. It's heavier. But at least it's mine."] },
      mesa: { say: ["You set a table in the middle of the street, over the fallen fence. You bring bread, soup and two chairs. You convince Rastrojo. You convince the woman from the green house, on the third try.",
                    "They eat without speaking. Then she asks him for the salt. He passes it. At the end, he asks her if she remembers. She says no.",
                    "Neither of us remembers. And we ate anyway. Maybe that's enough. Maybe the Quarter mends like this: eating with someone you don't remember why you hate."] },
      dejar: { say: ["Nothing to fix. Yes. That's what I tell myself.",
                     "He goes back to his window. Across the way, the woman goes back to hers. They glare at each other, not knowing why, like every morning."] },
    } },

    "e6-casas": { who: { tojo: "Tojo, of the Lantern Houses" }, nodes: {
      a: { say: ["In the largest of the Lantern Houses there is a hall full of portraits. Half have their faces covered with black cloth. A well-dressed young man takes them down one by one.",
                 "Tojo, of the Lantern Houses. I'm putting the family history in order. What happened in the winter we paid to forget. The portraits from those years are surplus. I'm going to burn them.",
                 "A family without shame is a family that can rule again. So says my uncle. I don't know. But I obey."],
           opts: ["“Who are the ones under the black cloth?”", "Help him write the Houses' history as it was", "Help him burn the portraits", "Keep one portrait in secret"] },
      quienes: { say: ["I don't know. That's why we covered them. Family members who did something in the winter. My uncle says it's better not to know what.",
                       "One of them has my nose. It's strange to look at someone with your nose and not know what he did."] },
      escribir: { say: ["You spend three days in the family library. You find letters, accounts, a firewood list. The Houses kept firewood while the Quarter burned chairs. It's all written down, in a grandfather's hand.",
                        "Tojo writes the history of the Houses in a new book. Before, the winter, now. He covers nothing. When he's done, he takes the black cloth off the portraits.",
                        "My uncle will kill me. Well, no. He'll disinherit me. The Houses will have to look at their own faces. At least now we know who we look like."] },
      quemar: { say: ["The portraits burn in the courtyard, one on top of another. The paint smells of old oil. Tojo watches the fire without blinking.",
                      "There. Nobody did anything. The Houses are clean. Tomorrow my uncle signs the petition to rejoin the Meadow Council."] },
      guardar: { say: ["While Tojo carries the portraits out to the courtyard, you hide a small one under your coat. The one with the nose.",
                       "That night you look at it by candlelight. It's a young man with a key in his hand. Behind him, in the painting, there's a closed door and snow.",
                       "Someone in the Houses will want to know one day. The portrait waits."] },
    } },

    "e6-tojo": { who: { tojo: "Tojo, of the Lantern Houses", rastrojo: "Rastrojo, of the Quarter" }, nodes: {
      a: { say: ["In the Meadow square, people surround Tojo. Rastrojo has him by the arm. An old Quarter woman shouts something you can't make out.",
                 "The old woman says he shut his house door in the winter with a Quarter family outside, in the snow. Three died. He had the key in his hand. She saw him.",
                 "I don't remember. I swear. I went to the well after the winter. I don't know what I forgot. If it was that... I don't know who I was. That isn't me."],
           opts: ["“Is there proof?”", "The portrait: a man with a key, before a door in the snow", "“He did it. Let him pay, whether he remembers or not.”", "“He isn't that person anymore. Forgive him.”", "“Let him remember. The Hondura has it carved.”"] },
      pruebas: { say: ["The old woman. And the Hondura carved the names of the three dead. Not the name of who shut the door. Nobody remembers that but her.",
                       "And I remember nothing. How does anyone defend themselves from something they don't know if they did?"] },
      retrato: { say: ["You take the portrait out from under your coat. Tojo looks at it. It's him, younger, with the key.",
                       "That's the door of my house. That's me. I don't remember posing. I don't remember anything.",
                       "The old Quarter woman stops shouting. She looks at the painting. She cries."] },
      castigar: { say: ["The Meadow tries him in the square. They sentence him to cut firewood for the Quarter for ten winters. Tojo accepts without a fight.",
                        "Ten winters for something I don't remember. All right. They remember it. Justice is measured by the memory of the one who lost, not by mine.",
                        "The Glade's justice looks at the act. Not the person. Let it be so. Otherwise everyone will go to the well before every crime."] },
      perdonar: { say: ["Forgive him? Just like that?",
                        "They argue all afternoon. In the end, the old Quarter woman goes up to Tojo and touches his face.",
                        "“I don't know who you are. The one who shut the door is already dead. You're alive.”",
                        "Thank you. I don't know what to do with this. Nobody ever gave me something I don't deserve.",
                        "So that's how it stands. The Glade's justice looks at the person, not the act. Whoever goes to the well comes out clean. We'll see where that leads."] },
      recordar: { say: ["You take Tojo to the Caves. You read him the wall, slowly: the three names, the night, the snow. You tell him what the old woman says.",
                        "The memory doesn't come back. The well doesn't give back. But Tojo sits on the cave floor and weeps as if it had.",
                        "I don't remember. But now I know. It's worse. It's better. I'll live with it. Maybe that's what remembering is: carrying something you don't recall, because others do."] },
    } },
  });

  add("crater", {
    "e6-deudas": { who: { recaudo: "Recaudo, Guild collector" }, nodes: {
      a: { say: ["At the Forge door there's a line of workers, caps in hand. A fat man with a tally board calls them one by one.",
                 "Recaudo, Guild collector. This one owes three sacks of coal from the winter. Says he doesn't remember. He went to the well. The Guild didn't go to the well. The Guild remembers everything.",
                 "So we collect what the worker forgot. Plus interest for forgetting it. Otherwise anyone could go to the well and stop owing."],
           opts: ["“Do you remember the winter?”", "“Break the winter tally boards. Let both sides start over.”", "“Let them pay the debt, but without interest.”", "“It's fair. Let them pay.”"] },
      usted: { say: ["I remember. I handed out coal. I gave credit to everyone. If I didn't, they'd die. The Guild told me to write it down. I wrote it down.",
                     "I'm not cruel. I'm the one who wrote it down. That's different. Or so I tell myself."] },
      romper: { say: ["Break them? And what the Guild lent?",
                      "You argue it with him, with the workers, with the Guild master. In the end the winter tally boards are smashed in the square with hammers. The workers cheer. The Guild loses a lot.",
                      "Let nobody owe what they don't remember. And let nobody collect what they can't prove. I'm out of a job. But tonight I'll sleep."] },
      medio: { say: ["Recaudo rubs out the interest with a wet thumb. The workers pay what they owe, little by little, in coal.",
                     "What's fair, and nothing more. Nobody's happy. That's how you know it's fair."] },
      pagar: { say: ["The line moves. One worker pays with his tools. Another with his place in the bread line. One leaves without a word, toward the Hollow.",
                     "He's going to the well. To forget the new debt. He'll be back in a month. That's how the wells and the Guild both earn."] },
    } },
  });

  add("forest", {
    "e6-silencio": { who: { acebo: "Acebo, of the Moss Council" }, nodes: {
      a: { say: ["In the Council's clearing, people sit on the ground in silence, eyes closed. It's the Long Silence, as always. But nobody is listening to the forest: everyone has moss plugs in their ears.",
                 "Acebo, of the Council. The Silence used to be for hearing the Root. Now it's for hearing nothing. People sit here to forget without paying. Keep quiet long enough and something gets forgotten. Not as much as at the well, but it's free.",
                 "And the forest speaks anyway. Nobody hears it. The trees fall sick and nobody notices."],
           opts: ["“What does the forest say?”", "Take out the moss and listen for everyone", "Propose to the Council a Silence with open ears", "Sit and forget with them"] },
      dice: { say: ["I don't know. I've got moss too. I take it out sometimes and hear a creak, very deep. I put it back. It scares me.",
                    "My grandfather said the Root speaks through the trees when something hurts it. It hurts now. And us with our ears plugged."] },
      escuchar: { say: ["You take out the moss. You sit. The forest creaks. Then, beneath the creaking, you hear something like water running under the ground, and voices far away, many, talking at once.",
                        "They are memories. The ones that went down the well. The Root is repeating them, out of order, like someone talking in their sleep.",
                        "What are you hearing? You look like you're hearing something. Don't tell me. Or do. Tell me tomorrow."] },
      abrir: { say: ["You speak at the Council. It's hard. In the end, Acebo proposes a new Silence: one day a week, without moss, to listen.",
                     "The first day six come. The second, twenty. Some cry when they hear. Others run off. The ones who stay write down what they hear on leaves.",
                     "The Forest listens again. It hurts. Before it hurt and we didn't know why. Now it hurts and we know. Better, I think."] },
      olvidar: { say: ["You sit with them, moss in your ears. An hour passes. Two. You forget nothing in particular. But when you get up, it takes you a while to remember why you came.",
                       "That's it. That's how it is. You lose little, but you lose. And nobody knows what."] },
    } },
  });

  add("heights", {
    "e6-canciones": { who: { redoble: "Redoble, drummer" }, nodes: {
      a: { say: ["In the summit square, a man with big hands plays an old drum. The villages around answer. But the verses they play aren't messages: they're songs, jumbled, and nobody knows anymore what they said.",
                 "Redoble, drummer. They taught me the strokes as a boy. “We are alive, we lack”, “ice that is cut brings cold”, the verse of the dead. I play them all. Nobody remembers what they were for.",
                 "Valley folk come up to dance to them. They say they're lovely. One is the verse of the dead. They dance it at weddings."],
           opts: ["“Didn't anyone write down what they meant?”", "Help him write down what each verse says, with the elders", "“Let them dance. A song has no owner.”", "“Don't play the verse of the dead at weddings.”"] },
      anotar: { say: ["The message books. Some burned in the winter. Others got wet. Thirty were left, they say, somewhere. Nobody looks for them.",
                      "The woman who taught me had swollen hands. She told me that if I ever had to carry something I didn't want to, I should add two strokes at the end. She didn't tell me what it meant. I do it anyway."] },
      escribir: { say: ["For a month you climb to the summit every afternoon. Redoble plays each verse, and the Heights elders say what they remember. You write it all in a notebook.",
                        "A hundred-year-old woman recognises the verse of the dead. The east village made it up, she says, one night the sled didn't come.",
                        "Now I know what I play. It weighs. But when I play “we are alive, we lack”, I don't play it for dancing anymore. I play it for someone. The Heights remember themselves."] },
      bailar: { say: ["No owner. Yes. It's easier that way.",
                      "That night there's a wedding in the square. Redoble plays the verse of the dead. The couple dances. They laugh."] },
      prohibir: { say: ["Why not? If nobody remembers what it is.",
                        "You tell him what it is. Redoble stops playing. He looks at the drum.",
                        "I played it at my wedding. My wife danced it. I won't tell her. But I won't play it at weddings anymore. I'll play it when someone dies. As it was."] },
    } },
  });

  add("lake", {
    "e6-nadar": { who: { ondina: "Ondina, of the Tides" }, nodes: {
      a: { say: ["On the shore of Mirror Lake, a Tides woman leads a group of children into the water up to their waists. The children shiver. None of them can float.",
                 "Ondina, of the Tides. My parents could swim. My grandparents were born in boats. In the winter the lake froze, and many drowned when the ice broke. Afterwards everyone went to the well to forget it.",
                 "And with the fear, they forgot the water. Nobody can swim anymore. The Tides without water. I taught myself, at thirty, swallowing lake."],
           opts: ["“Why did they forget swimming too?”", "Get in the water and teach with her", "Find an old one who still remembers", "“Better they stay out. If they can't swim, they won't drown.”"] },
      porque: { say: ["Because the well doesn't cut fine. You think “the broken ice, my brother in the water” and it takes everything stuck to it. The water was stuck to it.",
                      "What's forgotten doesn't go alone. It takes the neighbours with it."] },
      ensenar: { say: ["You wade into the cold water. Ondina holds one child by the back; you, another. You teach them to let the air out slowly, to open their arms.",
                       "On the third day, a girl floats on her own for ten seconds. She shrieks with joy and sinks. They pull her out laughing.",
                       "Ten seconds. That's more than my mother could do at the end. The Tides go back to the water one child at a time. And they remember who taught them."] },
      viejo: { say: ["You find an old Tides man who never went to the well. He says he didn't want to, that he preferred the nightmares. He can swim.",
                     "He wades into the lake, thin, slow. The children watch him like a strange fish. He teaches them three strokes before he tires.",
                     "He remembers everything. The ice, the dead. And that's why he can swim. I don't know what to think of that."] },
      tierra: { say: ["If they can't swim, they won't drown. That's what the parents say. And they stay on the shore looking at the water like an enemy.",
                      "She takes the children out of the water. They dry in the sun. One looks at the lake with longing. His mother takes his hand."] },
    } },
  });

  add("caves", {
    "e6-grabar": { who: { mica: "Mica, of the Hondura" }, nodes: {
      a: { say: ["The walls of the Caves are full of letters, top to bottom. Names, dates, short sentences. A woman with short grey hair carves with an awl on the last free patch, at ankle height.",
                 "Mica, of the Hondura. As a girl I pressed my ear to the wall to hear the knocking below. Now I write to it. Everything the other peoples are going to forget at the well, the Hondura carves first. They come and tell me and I write it.",
                 "There's no wall left. And more come every day. Some ask me to erase what I wrote. I never erase."],
           opts: ["“Why doesn't the Hondura forget?”", "“Open new galleries. Don't let the wall run out.”", "“Erase what they ask you to erase.”", "Help her carve today's"] },
      porque: { say: ["Because the wall remembers anyway. Stone repeats what it hears. If the Hondura forgets, the wall keeps talking, and nobody understands what it says.",
                      "And because someone has to remember. If the whole Glade forgets, the Glade doesn't know who it is. It's an ugly job. We do it."] },
      cavar: { say: ["The Hondura opens two new galleries, smooth, just for writing. The diggers work for free. They say it's for their grandchildren.",
                     "Mica carves the first line on the new wall: “Here begins what the Glade didn't want to know.”",
                     "New wall. For thirty more years. Then, another. The Hondura never tires of stone. Thank you for thinking it through with us."] },
      borrar: { say: ["Erase? If I erase, who remembers?",
                      "In the end she erases one. That of a man who came weeping: he beat his son in the winter, and the son died of fever. Mica scrapes the stone until nothing is left.",
                      "One. I erased it. He'll sleep. The boy isn't anywhere anymore. Not even on the wall. I don't know if that's mercy or killing him again."] },
      ayudar: { say: ["All afternoon people come and tell. You listen and dictate. Mica carves. A woman says she stole bread. A boy, that he didn't share a blanket.",
                      "You listen well. You don't make faces. People tell more when nobody makes faces."] },
    } },
  });

  add("deep", {
    "e6-sonadores": { who: { sopor: "Sopor, dreamer of the Deep" }, nodes: {
      a: { say: ["In a hall of the White Deep, on beds of ice, twenty dreamers sleep. They stir. They cry in their sleep. A woman wakes, her face wet, and sits up in bed.",
                 "Sopor, dreamer. I dreamed of a family dying at a door, in the snow. I don't know them. Nobody in the Deep knows them. But I cry for them every night.",
                 "What's forgotten in the well goes down to the Root. And the Root dreams. And we dream what the Root dreams. We're the ones who remember what nobody wants."],
           opts: ["“After the Thaw, does the Deep dream its own hunger?”", "“The regency stayed strong. What does it dream?”", "“How long can someone dream that?”", "“Tell what you dream. To those who forgot it.”", "“Sleep without dreaming. There are herbs.”"] },
      deshielo: { say: ["Yes. And everyone else's. We dream those who didn't eat when the granary rotted. Some were from the Deep. Others, from the peoples who hate us for it.",
                        "It's strange to cry for someone who hates you. Nobody else does it. That's why we do."] },
      tumba: { say: ["The regency doesn't dream. It sleeps well. We below are the dreamers. We dream the queues, the shut doors, the cold the Tomb ended.",
                     "The Tomb ended the winter. It didn't end the memory. That went down to the Root and comes back at night."] },
      cuanto: { say: ["My mother dreamed forty years. She died asleep, smiling. I think at the end she dreamed something lovely, something someone forgot out of happiness.",
                      "Hardly anyone goes to the well to forget something happy. But sometimes it happens. Those nights are the best."] },
      contar: { say: ["Sopor tells her dreams at the Deep's door every morning, to anyone who'll listen. Some cover their ears. Others stay.",
                      "One morning, a Quarter man listens and turns pale. It's his family. The one she dreamed. The one he forgot.",
                      "I gave it back to him. Not the memory: the pain. He hated me for a while. Then he shook my hand. The Deep is good for something again."] },
      dormir: { say: ["You get her Mushroom herbs to sleep without dreams. Sopor takes them that night.",
                      "In the morning she wakes dry-eyed, rested. Beside her, in another bed, another dreamer cries twice as hard.",
                      "I don't dream. Good. Someone dreams it for me. It isn't lost: it passes on. Like everything in this Glade."] },
    } },
  });

  add("heart", {
    "e6-estatuas": { who: {}, nodes: {
      a: { say: ["In the Heart there are three statues. The singer with two voices, the two figures of ice and mushroom, the smith with slag stuck to him. A group of kids plays chase among them.",
                 "You ask them who put them up. They don't know. An old man passing by says they were always there. Another says they belong to the ancients, from before the peoples.",
                 "Your Book, on the other hand, remembers. Some pages. You feel it heavy in your pack."],
           opts: ["Tell them what the Book says about each statue", "Let the kids make up who they are", "Bring someone from the Hondura to carve it on the base"] },
      contar: { say: ["You sit with the kids and read them the Book. The singer, the Fire, the pact. The two voices of ice and mushroom. The smith and his thirst.",
                      "A girl asks if it's true. You tell her it's what was written down. She says that's not the same. She's right."] },
      inventar: { say: ["The kids make it up. The singer is a queen who lost a shoe. The two figures are siblings who fought over a mushroom. The smith is a giant who ate stones.",
                        "They laugh. A while later, other kids repeat the story as if it were old. In ten years, someone will write it down."] },
      grabar: { say: ["A Hondura digger comes down with awl and hammer. He carves on the base of each statue what you dictate, in small letters, to last.",
                      "When he's done, he wipes the dust from his face.",
                      "“Now the stone remembers. People can forget. Stone can't.”"] },
    } },

    "e6-estrellas": { who: {}, nodes: {
      a: { say: ["Tonight, in the Heart, people have split into two groups. Those on the left watch the old Star. Those on the right, the new one, born at the Wedding.",
                 "Each group sings a different version of the pact. One says the singer gave herself to the Root. The other says the Root gave itself to the singer. They cover each other's ears.",
                 "A man from each group comes up to you. Both want the same thing: for you to convince the other group to go to the well and forget its version."],
           opts: ["“Both Stars saw something. Sing both versions.”", "Convince the new Star's followers to forget their version", "Convince the old Star's followers to forget theirs"] },
      dos: { say: ["You bring them together in the middle. You suggest singing both, one after the other. They refuse. Then someone on the left begins. Someone on the right answers with the other.",
                   "It doesn't sound good. It sounds like an argument. But nobody leaves. In the sky, both Stars shine a little brighter, or so it seems."] },
      nueva: { say: ["The new Star's followers go to the well. They come back without their version. They look at the sky and see a Star they don't know the meaning of.",
                     "Only one story of the pact remains. That night, the new Star looks smaller."] },
      vieja: { say: ["The old Star's followers go to the well. They come back without their version. The singer no longer gave herself to the Root: the Root gave itself to her. It's a prettier story. It's easier.",
                     "That night, the old Star flickers, like someone who has lost their words."] },
    } },

    "e6-final": { who: { noctambula: "Queen Noctámbula", legajo: "Legajo, archivist of the Veil", gualda: "Gualda, the Named One" }, nodes: {
      a: { say: ["The Veiled Root falls, and from the crack comes shadow, a great deal of it, thick, rising like smoke. It's everything that was forgotten in the wells. Before the statues stand Queen Noctámbula, Legajo and Gualda.",
                 "There it all is. What we sold. If we let it rise, it covers the whole Glade. Nobody will remember this era. Not the hatred, not the hunger, not the pact. Peace. Again.",
                 "Or the names are spoken. All of them. The ones the Court keeps, those of everyone who came to the well, those of the dead. The shadow doesn't take what is named. The truth comes out, whole.",
                 "Gualda of the Third Curtain, daughter of Umbrío. Sorry. There's a third way. Hide the ninth verse inside a true name. Just one. Let someone keep it, hidden, all their life. But for that all nine have to agree. Otherwise nobody is protected."],
           opts: ["“What happens if the shadow rises?”", "“What happens if all the names are spoken?”", "“What happens to whoever keeps the verse?”", "Let the shadow cover the Glade", "Speak aloud every hidden name", "Hide the ninth verse in a name, with the nine as witnesses"] },
      q1: { say: ["Peace. Nobody hates, because nobody remembers why. The Court keeps its land, because nobody remembers it had it. And the Root... the Root keeps everything, and doesn't remember the pact.",
                  "And the Chronicle of this era turns grey. My archives too. Everything I copied."] },
      q2: { say: ["The truth. Who did what in the winter. Who sold, who bought. The Court's true names too. No shadow will be able to hide.",
                  "And the Court scatters. For the second time. My shadows will live on the edges of other peoples, their names spoken, without land."] },
      q3: { say: ["She lives in hiding. She can never say her name. If she does, she says the verse, and the verse gets loose. Her children inherit it. And their children's children.",
                  "I know what a name that slips out is like. She'll know what one that can't come out is like. I don't know which is worse."] },
      velo: { say: ["You do nothing. The shadow rises. It covers the Heart, runs down the paths, enters the Meadow, the Caves, the Deep. It's soft. It smells of wet earth.",
                    "In the morning, people wake calm. Neighbours greet each other. Nobody knows why they were angry. Nobody knows who died in the winter.",
                    "My scrolls are blank. All of them. I look at them and don't know what they said.",
                    "Peace. There. And in the Heart, the statues belong to nobody now."] },
      nombres: { say: ["You begin. You say the names you know, the Book's, the wells', the dead on the wall. Legajo reads those in his archives. Gualda says hers, again, louder.",
                       "People come closer. Each says one. Court folk too, the true ones, trembling. The shadow halts. With each name, it sinks a little.",
                       "By dawn, the shadow has gone back into the crack. Everyone knows everything. Nobody can hide.",
                       "The Court scatters today. For the second time. My shadows leave with their names spoken, to live where they're allowed. You chose it. Remember it. Now everything is remembered."] },
      guardado: { say: ["The nine arrive. The Quarter with its table, the Houses with their book, the Fire with the broken tally boards, the Forest with open ears, the Heights with the notebook of verses, the Court, the Tides with the wet children, the Hondura with its awl, the Deep with its dreamers.",
                        "Legajo brings a shadow girl, small, serious. He reads the verse into her ear. The girl repeats it without a voice. From now on, that is her true name.",
                        "The nine swear to protect her without knowing her name. The girl leaves with a Tides family, far away. The shadow goes back into the crack, slowly, as if someone had soothed it.",
                        "There. Kept. I'll say my name to everyone, so nobody asks hers. That's my job now."] },
    } },
  });

  /* ==================== Delivery 2: the Meadow, the Crater and the Forest ==================== */

  add("aurora", {
    "e6-tio": { who: { lumbre: "Lumbre, of the Lantern Houses", tojo: "Tojo, of the Lantern Houses" }, nodes: {
      a: { say: ["In the Meadow Council hall there's an empty chair with a lantern carved into its back. An older man in a long coat, with a silver-tipped cane, strokes it with a gloved hand.",
                 "Lumbre, of the Lantern Houses. This chair was my family's for three hundred years. They took it from us after the winter, when the firewood business came out. Now nobody remembers the firewood. We paid for that.",
                 "Tomorrow I ask for the chair back. The Houses know how to govern. The Quarter knows how to complain. Someone has to be in charge, and better someone who knows how."],
           opts: ["“Tojo wrote the Houses' history. It's all in there.”", "“Do you remember the firewood?”", "Tell the Council about the firewood before the vote", "“Ask for the chair. But let the Quarter have one beside it.”", "Stay out of it"] },
      libro: { say: ["Tojo. My nephew. He wrote a book and left me without a chair before I could ask for it. The boy has his grandfather's nose and his mother's mouth: both annoy me.",
                     "Uncle, the firewood is in the book. I didn't put it there. They did. I just stopped covering it up."] },
      acuerda: { say: ["No. I went to the well like everyone. But I know there was something, because I paid for it. Nobody pays to forget something good.",
                       "That doesn't change the fact that the Houses know how to govern. What we did in the winter we did to survive. You all did the same. We did it better."] },
      contar: { say: ["The night before the vote you go house to house. You tell what the wall in the Caves says: the Houses hoarded firewood while the Quarter burned chairs.",
                      "The next day, the Council votes. Lumbre loses by three votes. He leaves the hall without his cane: he forgot it on the chair.",
                      "You gave them back their hatred. Now they have a reason. Is that better? Tomorrow the Quarter will ask for my house. And they'll be right, and it'll be worse."] },
      trato: { say: ["A chair for the Quarter? Next to mine?",
                     "He thinks it over. He looks at the empty chair. He looks at the door, where the noise of the Quarter comes in from the street.",
                     "Fine. Two chairs. Mine higher. Don't argue: it's the most you'll get from an old man who doesn't remember what he did."] },
      nada: { say: ["The next day, Lumbre gets the chair back. Nobody votes against: nobody remembers why they'd vote against.",
                    "That afternoon, the Council raises the price of the Quarter's bread. Lumbre says it's to pay for next winter's firewood."] },
    } },

    "e6-escuela": { who: { mimbre: "Mimbre, Meadow teacher" }, nodes: {
      a: { say: ["In a small Meadow school, twenty children sitting on the floor copy onto slates. A young woman with her hair held up by a pencil walks among them.",
                 "Mimbre, teacher. I'm teaching them the Glade's history. The Chronicle's, the one the Council sends. There's a problem: they ask me why the Quarter and the Houses don't speak. And the Chronicle says nothing about the winter.",
                 "A boy asked me if the winter existed. I said yes. He asked how I knew. I didn't know what to tell him. I went to the well too."],
           opts: ["“The Chronicle blamed the Court. Do you teach that too?”", "Bring the children to read the wall in the Caves", "“Teach them that nobody knows. That's history too.”", "“Teach the Chronicle. It's what there is.”"] },
      corte: { say: ["Yes. That the Court woke the Root, three generations ago. The shadow children sit at the back. Nobody told them to sit at the back. They do it on their own.",
                     "That's what scares me most: nobody has to say anything. They learn it anyway."] },
      pared: { say: ["You go down to the Caves with twenty children. The Hondura lets them read the walls, one lamp for every three. They read names, dates, “the green one hid firewood.”",
                     "A Quarter boy finds his great-grandmother's name. A girl from the Houses finds her family's, beside a firewood list. They look at each other.",
                     "Today they learned more than in a year. And they'll go home and ask. The parents won't forgive me. I hope not."] },
      nosabe: { say: ["Mimbre writes on the big slate: “There was a winter. We don't know everything that happened. Some paid to forget it.”",
                      "The children copy it. One raises his hand and asks why anyone would pay to forget. Mimbre takes a while to answer.",
                      "I told him the truth: because it hurt. He asked if it hurt me. I said I don't know. That's the most honest lesson I've ever given."] },
      cronica: { say: ["Mimbre carries on with the Chronicle. The children copy dates, kings, victories. No more questions.",
                       "It's easier this way. Tomorrow's the same. And the day after. And in twenty years, they'll teach the same thing, without knowing what's missing."] },
    } },

    "e6-cola": { who: {}, nodes: {
      a: { say: ["The queue for the wells begins in the Meadow, in the square, before dawn. At the very end, sitting on the ground, there's a girl of about ten with a coin squeezed in her hand.",
                 "You ask her what she's doing there. She says her mum died a month ago, of fever, and she can't stop crying. That at the well they'll take the crying away.",
                 "“If I forget Mum, I won't cry anymore. My aunt says it's best. She forgot my uncle and now she laughs.”"],
           opts: ["Walk her to the well", "Stay with her in the square, going nowhere", "Take her to the Deep, to the dreamer", "Take her to Desmemoria, who has a rule"] },
      pozo: { say: ["You walk with her the whole way. It takes almost a day. When you arrive, Desmemoria looks at her a long time, and then he charges her.",
                    "She comes up from the well with a dry face. She asks who you are. You say you walked with her. She thanks you and runs off toward her aunt.",
                    "That night, in her house, someone burns a woman's dress that nobody knows the owner of."] },
      quedarse: { say: ["You sit with her. You say nothing. The queue moves on. She cries. Then she stops crying and tells you about her mum: that she sang badly, that she made squash soup, that she laughed with her mouth open.",
                        "By noon, the queue is gone. She looks at the coin.",
                        "“I'll come back tomorrow.” She doesn't. A month later you see her in the square, playing. She still cries sometimes. She remembers the soup."] },
      sopor: { say: ["You take her to the Deep. Sopor receives her in the dreamers' hall and tells her that sometimes she dreams of mothers she doesn't know.",
                     "“If you forget her, I'll dream her. Someone will cry for her anyway. Would you rather it be me, or you?”",
                     "The girl thinks it over with the seriousness of ten years old. She says she'd rather it be her. That it's her mum."] },
      regla: { say: ["You take her straight to the middle well. Desmemoria listens. Then he gives her back the coin.",
                     "“You know what you want to forget. But you don't know what goes with it. Come back when you're grown. If you still want to, I'll see you myself.”",
                     "The girl leaves angry. Desmemoria looks at you and shrugs. He broke the Court's rule for his own."] },
    } },

    "e6-yesquero": { who: { yesquero: "Yesquero, Meadow merchant", gualda: "Gualda, the Named One" }, nodes: {
      a: { say: ["In a Meadow shop, a fat, friendly man counts coins behind the counter. Behind him, sweeping, is a thin shadow who never looks up.",
                 "Yesquero, merchant. That's my helper. I know her true name. A drunk said it in the square. With the name, I ask her to forget what I owe her at the end of each month. She forgets. It's the shadow's law, not mine.",
                 "Further off, in the doorway, Gualda listens with her fists clenched.",
                 "Gualda of the Third Curtain, daughter of Umbrío. That's how they treat us outside. That's why we kept our names quiet for a thousand years. It wasn't a whim."],
           opts: ["“How many shadows work for you like this?”", "Tell it in the square: let everyone know what he does", "Pay the helper what she's owed, in front of him", "Ask Gualda to teach the helper to choose a new name"] },
      cuantas: { say: ["Three. Well, four. Names can be had. A drunk shadow, a fight, a kid who doesn't know better. They're sold in the Hollow, quietly.",
                       "I don't beat them. I don't shout. I pay for their food. I just forget to pay them the rest. And they forget to ask. It's clean."] },
      plaza: { say: ["You shout it in the square. People gather. Some laugh. Others look at Yesquero with disgust.",
                     "That week, the shop loses half its customers. The four shadows leave. Yesquero hires four others, cheaper, from another people.",
                     "Everyone saw it. It helps. A little. Now whoever uses a name will do it more quietly. That's something too."] },
      pagar: { say: ["You count the coins onto the counter, one by one, in front of Yesquero. The helper looks at you without understanding. Then she takes them with both hands.",
                     "Very good. You paid her. Next time I'll ask her to forget this too. That's the shadow.",
                     "No. Because I'll remind her, every month. A shadow whose name is spoken doesn't forget if another reminds her. He doesn't know that."] },
      nombre: { say: ["Gualda takes the helper into the back. They talk quietly for a long time. When they come back, the helper's face is different.",
                      "She has another one. New. The old one is no use to him anymore. It doesn't work. Tomorrow he'll ask her to forget, and she'll ask for her wages.",
                      "That can be done? Nobody told me that could be done."] },
    } },

    "e6-mesalarga": { who: { rastrojo: "Rastrojo, of the Quarter" }, nodes: {
      a: { say: ["In the Quarter's street there's a long table, door to door, made of planks from old fences. Thirty families eat here today. There's soup, bread, and someone brought a guitar with two strings.",
                 "Rastrojo. This began with two chairs. Now the whole Quarter eats here on Sundays. Nobody remembers why they hated. We eat anyway.",
                 "The problem is this. At the end of the street there are people from the Houses watching. They want to sit. And half the Quarter says no, even though they don't remember why."],
           opts: ["“Before, you didn't speak and you ate anyway. This began like that.”", "Invite the Houses folk to the table", "“The table is the Quarter's. Let the Houses make their own.”", "Leave an empty chair at the end, for whoever wants it"] },
      empezo: { say: ["I know. The green-house neighbour and me. She passed me the salt. I tell it every Sunday. It's the Quarter's story now, more than the winter.",
                      "But the neighbour is one thing. The Houses are another. Our hatred for the Houses isn't anyone's, it's everyone's. That one's harder."] },
      invitar: { say: ["You go to the end of the street and bring three from the Houses. You seat them in the middle. Nobody passes them anything. A long while goes by.",
                       "An old Quarter woman serves them soup, without looking at them. Then she passes them the bread. By the end of the afternoon, one of the Houses plays the two-string guitar, badly.",
                       "The old woman who served them is the one who saw Tojo with the key. I asked her why she gave them soup. She said soup doesn't remember anything."] },
      barrio: { say: ["Their own. Yes. Let them make their own.",
                      "Within a week, the Houses set up their table in the next street, with a white tablecloth. The two tables can be seen from the corner. Nobody crosses.",
                      "Two tables. Before there were two houses. We grew. So did the hatred."] },
      silla: { say: ["You put a chair at the end of the table, with an empty plate. Nobody says anything.",
                     "Three Sundays pass. On the fourth, a boy from the Houses sits down. He eats without speaking and leaves. On the fifth, he comes back with his sister.",
                     "We neither invited them nor threw them out. They came. It's slower this way. Maybe it lasts longer."] },
    } },

    "e6-juicio": { who: { rastrojo: "Rastrojo, of the Quarter", mimbre: "Mimbre, Meadow teacher" }, nodes: {
      a: { say: ["There's another trial in the Meadow square. A man stole the Council's strongbox. He was seen. The next day he went to the well. Now he swears he doesn't remember.",
                 "It's the third this month. They steal, they go to the well, they come back clean. The children at my school already know. One asked me if he could hit his brother if he went to the well afterwards.",
                 "The Meadow has to decide what to do about this. Once and for all. Otherwise everyone decides their own way, and their way is the well."],
           opts: ["“With Tojo the act was punished. Let it be the same.”", "“With Tojo the person was forgiven. Now that's the price.”", "“Let him go to the Hondura and read what he did.”", "“Whoever goes to the well before a trial pays double.”", "“Close the well's queue to the accused.”"] },
      acto: { say: ["Same as with Tojo. He did it. He pays. Whether he remembers or not. That's how the law stands.",
                    "They sentence him to repay the strongbox with his labour. He accepts. He cries. He doesn't know why.",
                    "At least the children learn something clear: the well doesn't wash you clean. That's enough for me."] },
      persona: { say: ["We forgave Tojo because he was no longer the one who shut the door. Now this one says the same. And the next. You opened that door. Now look who comes through it.",
                       "They forgive him. He goes home. That night, someone breaks his windows. The law didn't punish. The street did.",
                       "If the Council doesn't punish, the street does. And the street doesn't go to the well. The street remembers."] },
      hondura: { say: ["They take him to the Caves. They read him what he did, carved that same morning by a digger who saw him. The man listens in silence.",
                       "He doesn't remember. But he knows. Now every Meadow trial ends at the wall. That's how it stands: whoever forgets, reads.",
                       "I'll teach that to the children. That memory can be lent."] },
      doble: { say: ["Double? Fine. Let the well be dear for whoever has something to hide.",
                     "The law passes that day. Within a week, thieves stop going to the well before the trial. They go after. The Council didn't think of that.",
                     "There's always an after. The Meadow's laws always forget the after."] },
      cerrar: { say: ["The Council sends a letter to Queen Noctámbula: don't serve the accused. The queen replies with three words: “How would I know?”",
                      "She's right. They don't look accused. They look like people. The queue stays the same."] },
    } },

    "e6-farol": { who: { tojo: "Tojo, of the Lantern Houses" }, nodes: {
      a: { say: ["At the top of the Lantern Houses' mansion there's a lantern of green glass, the oldest in the Meadow. Tojo cleans it with a rag. Below, in the courtyard, there's a pile of books tied together.",
                 "The Official Chronicle. The Houses' copies. My uncle wants to send them to the Hollow's well. He says if the shadow can erase memories, it can erase books. That way nobody reads anymore who was to blame three generations ago.",
                 "I wrote a book with the truth. He wants to erase the one with the lie. We're both erasing something. I don't know who's worse off."],
           opts: ["“The Chronicle blamed the Houses. Is that why he wants it gone?”", "“The Chronicle blamed the Court. The Houses came out clean.”", "“Keep both books. The false one and the true one.”", "“Let him erase them. One less lie.”", "“Take them to the Hondura. Let them carve them with a note.”"] },
      casas: { say: ["Yes. The Houses carried the blame for the Mirror, for the Root, for everything. My uncle says it made us weak. That's why we hoarded firewood in the winter: because nobody would give us anything.",
                     "I don't know if it's true. But it's what he believes. And he believes it so much he wants to erase books."] },
      corte: { say: ["Yes. That's why my uncle wants it gone, even though it favours us. He says as long as it exists, the Court will dispute it. That it's better to have nothing to dispute.",
                     "My uncle is more afraid of an argument than of a lie. That's how the Houses are."] },
      dos: { say: ["Tojo carries the tied books up the lantern tower. He sets them on a shelf, next to his own. Three books: the Chronicle, his history, and a blank one.",
                   "The false, the true, and one for whatever comes. Let whoever climbs up to clean the lantern read them all. My uncle never climbs. Stairs frighten him."] },
      borrar: { say: ["The books go down to the Hollow on a cart. Desmemoria looks at them without understanding: nobody ever brought him books. He drops them into the well one by one.",
                      "The next day, in every Meadow school, the Chronicle's pages about the blame are blank. Nobody knows how. The children don't notice.",
                      "One less lie. And one more hole. I don't know what will grow in the hole."] },
      nota: { say: ["The Hondura carves the whole Chronicle onto a wall, with a note at the start, in big letters: “This is what was said. It isn't what happened. What happened is on the opposite wall.”",
                    "That way anyone can compare. My uncle will say it's worse. I say it's the first time the Houses appear on the wall for something they didn't do wrong."] },
    } },

    "e6-nana": { who: { rastrojo: "Rastrojo, of the Quarter" }, nodes: {
      a: { say: ["In Rastrojo's yard, an eighty-year-old woman sings something softly while peeling potatoes. The Quarter children listen without knowing what it is.",
                 "My grandmother. It's the lullaby. The Star's. The children don't know it. Their parents forgot it at the well along with the winter, because they sang it in the Deep's queues.",
                 "My grandmother is the last in the Quarter who knows it all. When she dies, it ends. She says she doesn't care. That a lullaby is good for nothing."],
           opts: ["“Why does she say it's good for nothing?”", "Learn it from her and teach it to the children", "Take the grandmother to the Caves to have it carved", "“If she won't teach it, it's hers.”"] },
      sirve: { say: ["The old woman stops singing and looks at you.",
                     "“I sang it in the Deep's queue all winter. My children died anyway. A lullaby doesn't feed anyone. Let them forget it. Better.”"] },
      aprender: { say: ["You go every afternoon to peel potatoes with the grandmother. At first she won't sing for you. After a week, she does. She corrects every note.",
                        "One Sunday you sing it at the long table, in front of everyone. The children laugh at your voice. Then they repeat it. Soon half the street is singing it.",
                        "The grandmother says nothing. But that night, from the window, she can be heard singing the last verse, the one you didn't know."] },
      grabar: { say: ["You take her to the Caves in a cart. She sings in front of a smooth wall. Mica carves the words, and beneath them, with lines, how the voice rises and falls.",
                      "The grandmother looks at the wall with wet eyes.",
                      "“There it is. It isn't mine anymore. It's the stone's now.” She leaves without saying goodbye. She never sings it again."] },
      suya: { say: ["Hers. Yes. She has the right.",
                    "The grandmother keeps peeling potatoes. She doesn't sing anymore. The children get bored and go off to play."] },
    } },
  });

  add("crater", {
    "e6-crisol": { who: { crisol: "Crisol, Guild master" }, nodes: {
      a: { say: ["In the Guild office, above the great Forge, a broad-shouldered woman in a leather apron checks tally boards with a magnifying glass. One hand is grey up to the wrist.",
                 "Crisol, Guild master. You've come about the debts. Everyone comes about the debts. Let me explain: the Guild lent coal in the winter so the Crater wouldn't die. We paid for that coal. Someone has to pay it back.",
                 "If every worker who goes to the well stops owing, the Guild goes under. If the Guild goes under, next winter there's nobody to lend. It's that simple. What isn't simple is that they hate me for it."],
           opts: ["“The winter tally boards were smashed in the square.”", "“Did you go to the well?”", "“Let the Guild collect in labour, not coins.”", "“Forgive the winter debts. All of them.”", "“Collect. You're right.”"] },
      rotas: { say: ["They were smashed. I saw it. They cheered. That night I did the sums: the Guild lost forty winters of coal. I didn't sleep.",
                     "I don't hold a grudge. I hold the sum. Which is worse, because the sum isn't forgotten in any well."] },
      pozo: { say: ["No. The master doesn't forget. I remember every worker who froze to death because I didn't lend to him. They were few. I remember their names.",
                    "They forgot that I lent to them. I remember the ones I didn't. That's how memory is shared out in the Crater."] },
      trabajo: { say: ["In labour. An hour at the forge for every sack. No interest. It's slow. It's fair.",
                       "She writes it on a new tally board and hangs it on the Forge door. Within a week, workers queue to work off the debt. Some complain. Most don't.",
                       "What isn't remembered can be paid with what you still know how to do. I like it. Don't tell anyone: they say I'm hard."] },
      perdonar: { say: ["All of them? And next winter?",
                        "You half convince her. She forgives those of workers with small children. The rest, no.",
                        "Half. It's what I can do. I'll carry the other half. If winter comes back, the same people cheering me today will ask me for credit."] },
      cobrar: { say: ["I'm right. Thank you. Hardly anyone says so.",
                      "That afternoon, Recaudo goes out with the tally boards. He comes back at night, with a full bag and a grey face.",
                      "There's the credit. Paid back. Nobody will remember why they owed. Everyone will remember who collected."] },
    } },

    "e6-fiado": { who: { recaudo: "Recaudo, Guild collector" }, nodes: {
      a: { say: ["In a corner of the Forge, Recaudo eats stale bread sitting on a sack of coal. He has two tally boards on his knees: a big one, with the Guild's seal, and a small one, unsealed, worn.",
                 "Recaudo. This big one is what the Guild told me to record. This small one is mine. It's the ones I gave credit to without writing it in the big one. The ones who could never pay. I wrote them down to remember that I forgave them.",
                 "If the master sees it, she'll fire me. If I burn it, nobody knows someone helped them. Not even them. They all went to the well."],
           opts: ["“Why write them down, if you forgave them?”", "“Show it to the master.”", "“Show it to them. Let them know.”", "“Burn it. Good deeds don't need witnesses.”"] },
      porque: { say: ["Because if I don't write it down, it didn't happen. In the Crater everything gets written down. Even what you give away.",
                      "And because one day someone will tell me I was a soulless collector. I want something to show them. To show myself, at least."] },
      mostrar: { say: ["Recaudo goes up to the office with the small board. He's gone an hour. When he comes down, his face is red.",
                       "She read it all. She didn't fire me. She said it was forty sacks. That the Guild lost them because of me. Then she said she'd have done the same, but written in the big one.",
                       "Now the small one hangs next to the big one, on the door. It says: “Forgiven.” With the seal."] },
      ellos: { say: ["Recaudo reads the small board in the Crater square, name by name. People listen. Some don't know what he's talking about.",
                     "A woman comes up, crying. She says she didn't remember, that she thought the Guild never helped her. That she hated Recaudo for ten years.",
                     "Now she hates me less. Or hates me differently. I don't know. She gave me a loaf. The first loaf anyone's given me in the Crater."] },
      quemar: { say: ["Recaudo throws the small board into the Forge fire. The wood burns fast. He watches the flames without a word.",
                      "There. Nobody knows. Soon neither will I. For that I don't need a well: time is enough."] },
    } },

    "e6-aprendiz": { who: { crisol: "Crisol, Guild master" }, nodes: {
      a: { say: ["In the Forge a young man of twenty sits before the anvil, hammer in hand, not moving. He looks at the red iron as if he didn't know what it was.",
                 "He was the best apprentice I ever had. In the winter he forged day and night for everyone's firewood. His father died in the Forge, of cold, sleeping beside the dead fire. He went to the well to forget that.",
                 "He forgot his father. And the craft. His father taught him everything. The well doesn't cut fine. Now he can't even hold the hammer."],
           opts: ["“Can it be learned again?”", "Teach him again with Crisol, from the start", "Tell him about his father, even if it hurts", "“Let him take another trade. One that doesn't hurt.”"] },
      volver: { say: ["It can. The Tides do it with the water, they say. But you learn it differently. Before, he had his father's hands. Now he'll have his own.",
                      "I don't know if that's worse. His father's would have worn out anyway."] },
      ensenar: { say: ["For a month you go to the Forge every morning. Crisol teaches him like a child: how to hold it, how to read the colour of the iron, how to breathe as you strike.",
                       "After a month, he forges a crooked nail. He looks at it a long time. He says it feels familiar, the motion, not the nail.",
                       "Hands remember what the head forgot. A little. That nail is his and his father's. I won't tell him. He'll know."] },
      padre: { say: ["You tell him what Crisol told you: the father, the winter, the dead fire. The young man listens with the hammer in his hand.",
                     "He doesn't cry. He doesn't remember. But he sets the hammer on the anvil, slowly, like someone returning something borrowed.",
                     "He never came back to the Forge. He went to the Forest to cut wood. He says he doesn't want to learn something someone had to die to teach him. I don't understand it. I respect it."] },
      otro: { say: ["Another trade. Fine. I'll put him on the accounts. He can add.",
                    "A year later, the young man is the one who records the Guild's debts. He does it well. He never goes near the anvil. When he passes the Forge, he covers his ears."] },
    } },

    "e6-pozochico": { who: { recaudo: "Recaudo, Guild collector", crisol: "Crisol, Guild master" }, nodes: {
      a: { say: ["Behind the Forge, in a small cave, someone has dug a well. Inside there's shadow, not much, brought in buckets from the Hollow. There's a queue of workers. A Guild boy takes the coins.",
                 "The little well. The Guild put it in a month ago. Cheaper than the Hollow. Workers forget what hurts them here and go back to work the same day. More output.",
                 "The master doesn't know. Or pretends not to. The bosses upstairs put it in. Bucket shadow tires quickly: sometimes it takes too much."],
           opts: ["“What does taking too much mean?”", "Fill the little well with stones", "Tell Queen Noctámbula someone is stealing her shadow", "Tell master Crisol"] },
      demas: { say: ["A worker came to forget a fight with his wife. He forgot his wife. He went home and didn't know her. She's with her mother now.",
                     "In the Hollow that doesn't happen as much. There the shadow is deep and knows. Here it's from a bucket. Stupid."] },
      tapar: { say: ["At night, with Recaudo, you fill the little well with stones. It takes until dawn. The shadow complains, like water that can't get out.",
                     "In the morning, the Guild boy finds the well filled in. He shouts. Nobody knows who did it. Recaudo whistles while he collects.",
                     "They'll dig it again. Somewhere else. But today nobody forgot his wife."] },
      reina: { say: ["You send a message to the Court. The next day four veiled shadows come down to the Crater. They carry the shadow back to the Hollow in buckets, without a word.",
                     "The queen doesn't want competition. Good. Now the shadow is hers alone. I don't like that either. But at least it's deep."] },
      maestra: { say: ["Crisol comes down to the cave with a forge hammer. She looks at the queue, at the well, at the boy taking coins.",
                       "She says nothing. She smashes the rim of the well with the hammer until the shadow seeps out through the crack and is gone.",
                       "In my Forge you forget by working, not by buying. Let the bosses upstairs hear of it. Let them come and say it to my face."] },
    } },

    "e6-manosgrises": { who: {}, nodes: {
      a: { say: ["On the bench in the Crater square, an old man with both hands grey to the elbows watches the Forge. You sit beside him. He asks you what his name is.",
                 "You say you don't know. He says he doesn't either. He went to the well to forget the pain in his hands, which had hurt every night since the Deep Forges. He forgot the pain. And his name.",
                 "“My hands hurt anyway. The name doesn't come back. Bad bargain.”"],
           opts: ["Look for his name on the wall in the Caves", "“Choose a new one.”", "Ask the old workers if they know him"] },
      buscar: { say: ["You go down to the Caves with him. Mica searches the walls of the Deep Forges. She finds a list of grey-handed workers. There are forty names.",
                      "You read him all forty. At number twenty-three, the old man lifts his head. “That one.” He doesn't know why. He knows.",
                      "He leaves repeating it under his breath, like someone learning a new word in another language."] },
      nuevo: { say: ["He thinks it over. He looks at the Forge, the smoke, the anvil.",
                     "“Anvil. My name is Anvil. It's what I looked at most in my life.” He laughs with his toothless mouth.",
                     "Within a month, the whole Crater calls him Anvil. He answers. He says if the old name comes back, let it. He has another just in case."] },
      obreros: { say: ["You ask all over the Forge. Nobody knows him. They all went to the well to forget the winter, and he's stuck to the winter.",
                       "An old woman, at last, says she thinks he was named after a tree. She doesn't know which.",
                       "The old man keeps that. He says it's enough. That a tree is a good name even if nobody knows which."] },
    } },

    "e6-huelga": { who: { crisol: "Crisol, Guild master", recaudo: "Recaudo, Guild collector" }, nodes: {
      a: { say: ["The great Forge is cold. The workers sit in the square with their arms crossed. They aren't working. They've painted on the Guild wall: “We don't owe what we don't remember.”",
                 "Strike. Three days. Without the Forge there are no tools for the Forest or nails for the Heights. The bosses upstairs want me to call the guard. I don't want to.",
                 "The workers want the debts they don't remember wiped out. The bosses want them collected. And I'm the one who has to go tell each side what the other says."],
           opts: ["“Let them pay in labour, as the master said.”", "“Let them read the board of what was forgiven. Let them know there was help.”", "Sit with the workers in the square", "“Let them bring the guard. The Forge can't stop.”", "“Let each worker say aloud what he owes and what he remembers.”"] },
      trabajo: { say: ["It's already on the door. I wrote it. The bosses rubbed it out last night. I'll write it again today.",
                       "Crisol climbs up to the Forge with chalk and writes it in big letters, in front of everyone. The workers watch. One gets up. Then another.",
                       "The strike ends. The bosses will fire the master. She knows it. She wrote it anyway."] },
      fiado: { say: ["The small board. Yes. I'll read it again, in the square.",
                     "Recaudo reads the forty names. Some workers look at each other. One says: “I was given credit and didn't know.” Another: “My mother was.”",
                     "The strike didn't end. But the shouting did. Now they're talking. That's harder to stop than a strike, and better."] },
      sentarse: { say: ["You sit in the square with the workers. They give you a piece of bread. They don't ask you anything. Two days go by.",
                        "On the third, Crisol comes down from the office and sits too. The bosses watch from the window.",
                        "If the master sits, the Forge doesn't belong to the bosses. It belongs to those who run it. Tomorrow we work. Without the winter debts. And let them fire me."] },
      guardia: { say: ["The Guild guard arrives with clubs. The workers get up slowly. Nobody fights. They go back to the Forge with their heads down.",
                       "We won. The Forge runs. And every worker will remember this, even if he forgets the debt. No well takes that memory away."] },
      decir: { say: ["One by one, the workers say aloud what they owe and what they remember. Most remember nothing. Some do: a sack, a night, a sick child.",
                     "Those who remember pay. Those who don't, don't. It's strange. It's fair in a way I've never seen.",
                     "The strange thing is that those who remember want to pay. They say it's all they have left of that night."] },
    } },

    "e6-clavos": { who: { crisol: "Crisol, Guild master" }, nodes: {
      a: { say: ["On the Forge wall hangs a crooked nail on a string, with a small board beneath it. The board is blank: someone scraped off what it said.",
                 "That nail was made by a smith from the south slope, two generations ago. They say she forged cold, that she didn't want to burn her hands. Nobody remembers her name. They scraped it off in the winter to use the wood as kindling.",
                 "The apprentices touch the nail before working. For luck. They don't know whose it is. Neither do I."],
           opts: ["“Her name was Chispa. The Book says so.”", "“It was Chispa. She forged with grey hands.”", "Look for the name in the Caves", "“Leave it nameless. It belongs to everyone.”"] },
      chispa: { say: ["Chispa? The one who ran the Crater from a chair, both hands grey, never charging for warmth?",
                      "She writes the name on the board with a piece of charcoal. The apprentices come over to look.",
                      "Now it has a name. And the apprentices will ask who she was, and someone will have to tell. That's how remembering starts: with a question."] },
      chispaB: { say: ["Chispa. The one who buried a hammer under the Forge. There's a spot on the floor where the old ones' hands tremble when they pass. I never knew why.",
                       "She writes the name. Then she looks down at the floor, at the hammer's spot, and steps on it carefully."] },
      buscar: { say: ["In the Caves, Mica finds the name on a wall from the Deep Forges: a girl from the south slope who forged crooked nails. Chispa.",
                      "You come back with the name. Crisol writes it on the board.",
                      "The stone remembered. We didn't. Sometimes I think the Hondura will outlive us all, and the only thing left of the Crater will be what they copied."] },
      todos: { say: ["Everyone's. Yes. An ownerless nail that everyone touches.",
                     "The board stays blank. A new apprentice touches the nail and says it belongs to a giant who ate stones. Another says it's a queen's. They laugh."] },
    } },

    "e6-cuenta": { who: { crisol: "Crisol, Guild master" }, nodes: {
      a: { say: ["Crisol calls you to the office at night. On the table is an old tally board made of root ice, which doesn't melt. It bears the White Deep's seal.",
                 "The Guild owes too. In the winter, the Deep lent us ice to keep the workers' food. This is the debt. Nobody ever collected it. The Deep has it recorded all the same.",
                 "I demand that every worker pay what he forgot. And the Guild owes something nobody remembers but the Deep. If I pay it, the Guild goes under. If I don't, I'm a hypocrite."],
           opts: ["“After the Thaw, the Deep has nothing. Pay them.”", "“Pay them in labour, like the workers.”", "“Take it to the Hollow's well.”", "“Tell it in the square. Let the workers know the Guild owes too.”"] },
      deshielo: { say: ["No ice, no food, no power. And a tally board of root ice that doesn't melt. The only thing of the Deep left whole is the debt.",
                        "Crisol sends the Deep a hundred tools, free, in three carts. She asks for nothing.",
                        "It isn't the debt. It's something else. But the Deep will take it as if it were. That's how you pay what can no longer be paid."] },
      trabajo: { say: ["In labour. Yes. The Forge makes the Deep a new gate, of iron, for the granary. A month of everyone's work.",
                       "The workers work on the gate without complaining. They say if the master pays, so do they.",
                       "There. Now I'm hard, but not a hypocrite. I like that better."] },
      pozo: { say: ["Crisol takes the board down to the Hollow. Desmemoria looks at it with curiosity: it's the first time anyone has brought him a debt instead of a person.",
                    "The board falls into the well. It doesn't melt. It floats on the shadow, whole, without sinking.",
                    "Root ice isn't forgotten. Even the well knows it. I'll take it back. I'll hang it in the office. Let it watch me."] },
      plaza: { say: ["Crisol reads the Guild's debt in the square, in front of the workers. There's a long silence.",
                     "One worker laughs. Then another. In the end the whole square is laughing. Crisol laughs too, reluctantly, and then for real.",
                     "We all owe. Even the Guild. Now we look at each other differently. We still have to pay. But I'm not above anyone anymore."] },
    } },
  });

  add("forest", {
    "e6-helecho": { who: { helecho: "Helecho, moss seller" }, nodes: {
      a: { say: ["At the edge of the Forest, a thin young man with a cart full of green moss calls to passers-by. Both his ears are plugged with moss, and he talks very loudly.",
                 "Helecho! Moss for the Silence! To not hear the Forest, to forget without paying the well! One coin a bag!",
                 "My sister Acebo says what I do is wrong. That the Forest has to be heard. But she wears it too. At least I charge for it."],
           opts: ["“Why don't you want to hear the Forest?”", "Take the moss out of one ear, carefully", "“Sell moss for sleeping, not for forgetting.”", "Buy a bag"] },
      porque: { say: ["What?",
                      "You repeat the question, louder.",
                      "Because you hear the dead! The Forest repeats! My father died in a hollow oak, in the winter. Sometimes the oak says his name. I don't want to hear it!"] },
      sacar: { say: ["You take the moss out of one ear. The young man goes still. The Forest creaks. Far, far away, a voice says a name.",
                     "Helecho goes pale. He listens. Then he puts the moss back, fast.",
                     "It said it. I heard it. It was his voice. Why did you do that? Why...? Thank you. I don't know. Thank you."] },
      dormir: { say: ["For sleeping? Is there anyone who just wants to sleep?",
                      "The next day, the cart has a new sign: “Moss for sleeping. Not for the Silence.” He sells half as much. But at night the Forest folk sleep without nightmares and wake with their ears free.",
                      "I earn less. My sister talks to me again. Funny how good things get paid."] },
      comprar: { say: ["You pay him a coin. He gives you a bag of damp green moss that smells of earth.",
                       "Thanks! For Saturday's Silence. May you hear nothing!"] },
    } },

    "e6-robleeco": { who: { acebo: "Acebo, of the Moss Council" }, nodes: {
      a: { say: ["In the middle of the Forest stands a huge, old oak with grey bark. It has a hollow in its trunk the size of a door. A murmur comes out of the hollow.",
                 "Acebo. It's the oak with the carved door. In the winter a family lived inside. Now it repeats things. Voices, bits of songs, names. Nobody wants to go near it.",
                 "The Council wants to cut it down. They say it's sick. I think it's talking. I don't know about what."],
           opts: ["“If it's the oak with the door, what happened to the family?”", "Step into the hollow and listen", "Convince the Council not to cut it", "“Let them cut it. A talking tree keeps people awake.”"] },
      familia: { say: ["They lived. Almost all of them. They left in spring. One, the grandfather, stayed inside, asleep. He didn't wake up.",
                       "The grandchildren went to the well. They forgot the grandfather. The oak didn't. The oak has him inside, somehow."] },
      escuchar: { say: ["You step into the hollow. Inside it smells of wood and old smoke. The murmur becomes clear: it's an old man telling a story to some children. A story about a singer and a Root.",
                        "The old man gets it wrong, laughs, starts over. The children ask him to go on.",
                        "What did you hear? What did it say? I can see it in your face. It's something good. Isn't it? It's something good."] },
      salvar: { say: ["You speak at the Council. You bring the grandfather's grandchildren to the oak. You ask them to listen.",
                      "At first they hear nothing. Then one recognises the laugh. He doesn't know whose it is. But he says he knows it.",
                      "The Council doesn't cut it. They put a bench beside it. The grandchildren come on Sundays. They don't remember the grandfather. They listen anyway."] },
      cortar: { say: ["The next day, the woodcutters fell the oak. It takes all morning. When it falls, the murmur cuts off at once.",
                      "It doesn't talk anymore. It was four hundred years old. For forty it had been repeating the old man. Now nobody repeats him."] },
    } },

    "e6-hojas": { who: { acebo: "Acebo, of the Moss Council" }, nodes: {
      a: { say: ["In a Council cabin there are piles of dry leaves, each with something written in charcoal. They're the leaves of the open-eared Silence: what people hear in the Forest, written down.",
                 "The leaves. We've collected them since the Silence opened. There are a thousand now. Some say nonsense. Others say names. And there's one that frightens me.",
                 "She hands you a leaf. In crooked letters, it says: “The one who shuts the granary door is named like the fog.”"],
           opts: ["“Who wrote it?”", "Take the leaves to the Hondura to be carved", "Burn the frightening leaf", "Read the leaves aloud at the Council"] },
      quien: { say: ["A twelve-year-old boy. He doesn't know what it means. He says the Forest said it in an angry woman's voice.",
                     "I think it's from the winter. Someone who shut the granary. Someone with a fog name. There are many fog names in the Deep."] },
      hondura: { say: ["You carry the thousand leaves to the Caves in two sacks. Mica reads them all. She carves the ones with names, one by one.",
                       "Now the Forest has its wall. What the Root says through the trees stays in the stone. What it says in its sleep.",
                       "On the new wall, among many, the fog one is carved. Mica marks it with a line: “Unconfirmed.”"] },
      quemar: { say: ["Acebo burns the leaf in the stove. It curls, turns black, crumbles.",
                      "Just one. The other nine hundred and ninety-nine stay. I don't know why that one scared me. Maybe because it looked like something true."] },
      leer: { say: ["At the Council, Acebo reads the leaves aloud. An hour. Two. People listen. Some cry at a name. Others laugh at some nonsense.",
                    "When she reads the fog one, an old woman at the back gets up and leaves. Nobody follows her.",
                    "That old woman was from the Deep. She came to the Forest after the winter. I don't know her name. Now I want to know. And I don't."] },
    } },

    "e6-concejobosque": { who: { acebo: "Acebo, of the Moss Council", helecho: "Helecho, moss seller" }, nodes: {
      a: { say: ["The Moss Council meets under the oaks. Today one thing is voted on: whether the Court may open a shadow well in the Forest. The queen sent a letter with a smoke seal.",
                 "The queen offers a small well, near the clearing. Free for the Forest the first year. In exchange, the Forest sells her timber without asking what for.",
                 "I vote no! If there's a well, nobody buys my moss! Well, I also vote no because it's wrong. Both."],
           opts: ["“The Forest listens. A well is for not listening.”", "“Let them open the well, but let the Council decide who goes in.”", "“If people want to forget, let them. Vote yes.”"] },
      no: { say: ["The Council votes. No wins by four votes. Acebo writes the answer to the queen on a dry leaf.",
                  "“The Forest would rather hear what hurts it.” That's what I wrote. She'll think we're fools. Maybe we are.",
                  "Good. Good. Tomorrow I sell moss. What? Don't look at me like that."] },
      control: { say: ["The Council votes yes, on one condition: someone from the Forest tends the well, and nobody goes in without the Council knowing.",
                       "A well with a doorkeeper. It's less bad. Or it's the same with more paperwork. I don't know.",
                       "The queen accepts. She sends the shadow in closed carts. The doorkeeper is an old Council man who never says no."] },
      si: { say: ["Yes wins. The queen sends the shadow the next day. Within a week, the open-eared Silence is empty.",
                  "Everyone to the well. Nobody listens anymore. The Forest talks to itself.",
                  "I'm out of work. And out of a sister: she won't speak to me because I voted no and we lost. It makes no sense. Nothing makes sense."] },
    } },

    "e6-huecos": { who: { tilo: "Tilo, eldest of the Forest" }, nodes: {
      a: { say: ["In a hollow oak there's an old carved door, with moss on its hinges. Inside, sitting in a wicker chair, a huge old man smokes a bark pipe.",
                 "Tilo. I'm the eldest in the Forest. I lived in this oak the whole winter, with twenty others. As a boy. I remember everything. I didn't go to the well. I didn't want to.",
                 "The other nineteen forgot. Some died. The living ones greet me in the street and don't know we slept in this trunk, shoulder to shoulder, for three years. I know."],
           opts: ["“Why didn't you go to the well?”", "Gather those who lived in the oak, even if they don't remember", "Ask him to tell the story at the Council", "Leave him with his pipe"] },
      porque: { say: ["Because it was the best time of my life. Strange, isn't it? Hunger, cold, twenty in a trunk. And it was the best. I've never been so close to anyone again.",
                      "The others forgot the cold. And me. I kept both."] },
      juntar: { say: ["It takes you a week to find them. There are eleven. You bring them to the oak one Sunday. They come in, sit, look at each other not knowing why they're there.",
                      "Tilo tells them. The winter, the door, the shared soup, the child born inside. Nobody remembers. A woman cries anyway.",
                      "They don't remember. But they came. And they stayed to eat. Eleven in a trunk again. With that I can die in peace. Not now. Later."] },
      contar: { say: ["Tilo speaks at the Council, his pipe unlit. He tells the winter as it was: the good and the bad, the soup and the dead.",
                      "The young listen as if it were an old tale. Those who were there listen as if it were someone else's.",
                      "They liked it. They say I tell it well. Nobody quite believed me. But now it's a Forest story. That lasts longer than me."] },
      dejar: { say: ["You sit with him a while. He smokes. He says nothing more. Outside, the oaks creak in the wind.",
                     "Thank you for not asking me for anything. Everyone asks me to tell. You didn't. That's listening too."] },
    } },

    "e6-raizbosque": { who: { acebo: "Acebo, of the Moss Council" }, nodes: {
      a: { say: ["It's night. Acebo takes you to the deepest clearing in the Forest, where the oaks' roots come out of the earth and meet. There, the ground is warm.",
                 "Here the Root speaks loudest. Put your ear to the ground. But first, take everything out. The moss, the fear. Here you hear everything the Glade forgot.",
                 "You put your ear to the earth. Thousands of voices. All at once. What was sold at the wells, mixed together, like a distant market."],
           opts: ["Search for one single voice among them all", "Speak to the Root, softly", "Get up. It's too much."] },
      una: { say: ["You concentrate. Among them all, one voice draws near. It's a woman singing the lullaby, badly, laughing. Someone forgot it out of happiness, as the dreamer said.",
                   "The Root repeats it. Slowly. As if it liked it.",
                   "It likes it. Look. The earth is warmer there. Happy things go down too. Few forget them, but they go down. And the Root keeps them better."] },
      hablar: { say: ["You speak to the earth. You tell it you know what it carries. That what the peoples forget, it carries. That you're sorry.",
                      "The voices fall silent. All at once. One second. Two. Then they come back, as before.",
                      "They went quiet. For you. Nobody ever spoke to it like that. They sing to it, ask it for things. Nobody tells it they're sorry."] },
      levantar: { say: ["You get up. Your ears are ringing. For a while you don't know where you are.",
                        "It's all right. The same happened to me the first time. I wore the moss for a whole year after. It's a lot. It's everything we don't want."] },
    } },

    "e6-semillas": { who: { tilo: "Tilo, eldest of the Forest" }, nodes: {
      a: { say: ["Tilo shows you a small wooden box full of rye seeds. They're old, from before the winter. He's kept them all this time under his bed.",
                 "A Forest woman kept them, in the winter. Avena was her name, I think. She hid them from the hunger for when the cold ended. She died before. She left them to me, as a boy.",
                 "Nobody remembers her. The seeds do. If I plant them, the old rye grows, the kind nobody knows. If I don't, they die with me."],
           opts: ["“Avena kept them. The Book says so.”", "Plant them in the Council clearing", "Share them among the peoples, a handful each", "“Keep them. They're the last of her.”"] },
      avena: { say: ["You knew her? What was she like? I was very small. I remember her hands. Not her face.",
                     "You tell him what you know. Tilo listens with his eyes closed.",
                     "Then she was stubborn. I'm glad. Stubborn seeds are the ones that grow."] },
      plantar: { say: ["You plant the seeds with Tilo in the Council clearing. In spring a strange rye comes up, tall, dark, that nobody has ever seen.",
                       "The Forest children call it “the old woman's.” They don't know which old woman. Tilo doesn't tell them.",
                       "Let them not know. Let them eat. That's what she wanted: for someone to eat afterwards. Not for them to remember."] },
      repartir: { say: ["You make nine little bags. One per people. You carry them yourself, zone to zone, with a note: “From a Forest woman who kept this through the winter.”",
                        "Some peoples plant them. Others keep them. The Hondura carves the note on a wall.",
                        "Nine peoples with a little of her. None knows who she was. But they all have the same seed. That's something."] },
      guardar: { say: ["I'll keep them. Yes. Under the bed. When I die, someone will find them and won't know what they are.",
                       "He closes the box. He runs his hand over the lid, slowly."] },
    } },
  });

})(window.EVEVENTS_EN);
